// Standalone deployable build of SUPER KIRA GAME Ver.2.
// No dependencies and no sibling files are needed.


const LABEL = {kira:'キラ', devotee:'崇拝者', l:'L', investigator:'捜査員'};
const TEAM = role => ['kira','devotee'].includes(role) ? 'kira' : 'l';
const VERSION = '2.4';
const NPC_NAMES = ['夜神','竜崎','渋井丸','相沢','松田','伊出','模木','ワタリ','ペンバー','ジェバンニ','火口'];
const ROLES = ['kira','devotee','l','investigator','investigator'];
const pick = arr => arr[randomInt(arr.length)];
function shuffle(arr) {
  const r = [...arr];
  for(let i=r.length-1;i>0;i--){const j=randomInt(i+1); [r[i],r[j]]=[r[j],r[i]];}
  return r;
}
function makeGame(players, options={}) {
  if(players.length!==2) throw Error('2人揃ってから開始してください');
  let roles;
  do { roles=shuffle(ROLES); } while (TEAM(roles[0])==='kira' && TEAM(roles[1])==='kira');
  const names=shuffle(NPC_NAMES).slice(0,3);
  const chars=roles.map((role,i)=>({id:`c${i}`,role,team:TEAM(role),name:i<2?players[i].name:names[i-2],npc:i>=2,playerId:i<2?players[i].id:null}));
  return {
    players:players.map(p=>({id:p.id,name:p.name})), chars,
    round:1, phase:'role_reveal', roleReady:{}, discussionReady:{}, discussionUntil:0, nightUntil:0, briefingReady:{},
    minutes:Number(options.minutes||2),
    discussionSeconds:Number(options.discussionSeconds ?? Number(options.minutes||2)*60),
    finalDiscussionSeconds:Number(options.finalDiscussionSeconds ?? Number(options.minutes||2)*60),
    selections:{}, missions:[], votes:{}, allMissions:[],
    nightActions:{}, investigationsUsed:{}, searchUsed:{}, accuseUsed:{}, swapUsed:false,
    privateLogs:Object.fromEntries(players.map(p=>[p.id,[]])),
    guesses:{}, winner:null, endReason:null,
    threshold:null,
    events:['ゲームが始まりました。役職確認後、第1ラウンドの夜へ進みます。'],
    endedBy:null,
    created:Date.now()
  };
}
const myself=(g,pid)=>g.chars.find(c=>c.playerId===pid);
const byId=(g,id)=>g.chars.find(c=>c.id===id);
function setDiscussion(g,final=false,now=Date.now()) {
  g.phase=final?'final_discussion':'discussion'; g.discussionReady={};
  g.discussionUntil=now + (final?g.finalDiscussionSeconds:g.discussionSeconds)*1000;
}
function setNight(g,now=Date.now()) {
  g.phase='night'; g.nightActions={}; g.nightUntil=now+30_000;
}
function beginGame(players,opts={}){return makeGame(players,opts);}
function pushPrivate(g,pid,msg,kind='general'){g.privateLogs[pid].push({id:`${pid}-${g.privateLogs[pid].length+1}`,round:g.round,text:msg,kind});}
function err(message){throw Object.assign(new Error(message),{status:400});}
function assert(cond,msg){if(!cond)err(msg);}
function playersDone(g,obj){return g.players.every(p=>Object.hasOwn(obj,p.id));}
function missionId(g,pid){return `r${g.round}-${pid===g.players[0].id?'A':'B'}`;}

function advanceDiscussion(g,now=Date.now()) {
  if(g.phase==='final_discussion'){g.phase='final_vote';return;}
  if(g.round===2||g.round===3){g.phase='selection'; g.selections={}; return;}
  setNight(g,now);
}
function tick(g,now=Date.now()) {
  if(['discussion','final_discussion'].includes(g.phase) && now>=g.discussionUntil) {
    advanceDiscussion(g,now);return true;
  }
  if(g.phase==='night' && now>=g.nightUntil){
    for(const p of g.players)if(!Object.hasOwn(g.nightActions,p.id))g.nightActions[p.id]={action:'none',target:null};
    resolveNight(g,now); return true;
  }
  return false;
}
function checkChoice(g,ids,selfId){
  assert(Array.isArray(ids)&&ids.length===2&&ids[0]!==ids[1],'異なる2人を選んでください');
  assert(ids.every(id=>byId(g,id)),'参加者が不正です');
  assert(!ids.includes(selfId),'自分は任務に参加できません');
  assert(ids.some(id=>byId(g,id).npc),'NPCを少なくとも1人含めてください');
}
function act(g,pid,data,now=Date.now()) {
  const self=myself(g,pid);
  assert(self,'ルームに参加していません');
  assert(g.phase!=='finished' && g.phase!=='abandoned','ゲームは終了しています');
  const type=data?.type;
  if(type==='end_game'){
    // The cancel action does not reveal hidden roles or award a victory.
    g.endedBy=self.name;
    g.phase='abandoned';
    g.events.push(`${self.name}がゲームを終了しました。勝敗はつきません。`);
  } else if(type==='ack_role') {
    assert(g.phase==='role_reveal','役職確認の時間ではありません');
    g.roleReady[pid]=true;
    if(playersDone(g,g.roleReady))setNight(g,now);
  } else if(type==='ack_briefing'){
    assert(g.phase==='briefing','結果確認の時間ではありません');
    g.briefingReady[pid]=true;
    if(playersDone(g,g.briefingReady))setDiscussion(g,false,now);
  } else if(type==='ready'){
    assert(['discussion','final_discussion'].includes(g.phase),'議論フェーズではありません');
    g.discussionReady[pid]=true;
    if(g.players.every(p=>g.discussionReady[p.id]))advanceDiscussion(g,now);
  } else if(type==='unready') {
    assert(['discussion','final_discussion'].includes(g.phase),'議論フェーズではありません');
    delete g.discussionReady[pid];
  } else if(type==='select') {
    assert(g.phase==='selection','任務選出の時間ではありません');
    assert(!Object.hasOwn(g.selections,pid),'すでに選出しています');
    checkChoice(g,data.members,self.id);
    g.selections[pid]=[...data.members];
    if(playersDone(g,g.selections)){
      g.missions=g.players.map(p=>({id:missionId(g,p.id),round:g.round,selector:p.id,members:g.selections[p.id],outcome:null}));
      g.phase='voting';g.votes={};
      resolveVotingIfReady(g,now);
    }
  } else if(type==='vote') {
    assert(g.phase==='voting','任務投票の時間ではありません');
    const eligible=g.missions.filter(m=>m.members.includes(self.id));
    assert(eligible.length>0,'参加する任務がありません');
    assert(!Object.hasOwn(g.votes,pid),'すでに投票しています');
    const submitted=data.votes||{};
    assert(eligible.every(m=>typeof submitted[m.id]==='boolean'),'全参加任務について成功・失敗を選んでください');
    g.votes[pid]=Object.fromEntries(eligible.map(m=>[m.id,submitted[m.id]]));
    resolveVotingIfReady(g,now);
  } else if(type==='night') {
    assert(g.phase==='night','夜ではありません');
    assert(!Object.hasOwn(g.nightActions,pid),'今夜の行動は確定済みです');
    const action=data.action||'none';
    assert(['none','investigate','search','accuse','swap'].includes(action),'無効な行動です');
    if(action==='investigate') {
      assert(self.role==='l','Lだけが調査できます');
      assert((g.investigationsUsed[pid]||0)<2,'調査は2回までです');
      assert(byId(g,data.target)?.npc,'NPCを選択してください');
    } else if(action==='search') {
      assert(self.role==='investigator','捜査員だけが捜査できます');
      assert(g.round===4 && g.threshold===true,'捜査は第4ラウンドで任務2回以上成功時のみ可能です');
      assert(!g.searchUsed[pid],'捜査は1回までです');
      assert(byId(g,data.target)?.npc,'NPCを選択してください');
    } else if(action==='accuse') {
      assert(self.role==='investigator','捜査員だけが告発できます');
      assert(!g.accuseUsed[pid],'告発は1ゲーム1回までです');
    } else if(action==='swap') {
      assert(self.role==='devotee','崇拝者だけが使用できます');
      assert(!g.swapUsed,'ノートのすり替えは1回までです');
    }
    g.nightActions[pid]={action,target:data.target||null};
    // Fixed-duration night: never end early when both players submit.
    // No other player can infer role/ability from submission timing.
  } else if(type==='guess') {
    assert(g.phase==='final_vote','最終指名の時間ではありません');
    assert(self.team==='l','キラ陣営には指名権がありません');
    assert(!Object.hasOwn(g.guesses,pid),'すでに指名しています');
    assert(byId(g,data.target) && data.target!==self.id,'自分以外の人物を指定してください');
    g.guesses[pid]=data.target;
    const lPlayers=g.players.filter(p=>myself(g,p.id).team==='l');
    if(lPlayers.every(p=>Object.hasOwn(g.guesses,p.id))) {
      const kira=g.chars.find(c=>c.role==='kira');
      g.winner=lPlayers.every(p=>g.guesses[p.id]===kira.id)?'l':'kira';
      g.phase='finished'; g.events.push(g.winner==='l'?'L陣営の勝利！':'新世界の幕開け');
    }
  } else err('操作を選択してください');
  return g;
}

function resolveVotingIfReady(g,now){
  const required=g.players.filter(p=>g.missions.some(m=>m.members.includes(myself(g,p.id).id)));
  if(!required.every(p=>Object.hasOwn(g.votes,p.id)))return;
  for(const m of g.missions){
    m.outcome=m.members.every(id=>{
      const c=byId(g,id);
      if(c.npc) return c.team==='l';
      return g.votes[c.playerId][m.id]===true;
    });
  }
  g.allMissions.push(...g.missions.map(m=>({...m,members:[...m.members]})));
  g.events.push(`第${g.round}ラウンド：2つの任務が実施されました。結果は翌ラウンドに選出者へ通知されます。`);
  setNight(g,now);
}
function resolveNight(g,now){
  // All accusations are adjudicated only at the common 30-second night boundary.
  // This keeps night length and player action timing from disclosing the investigator.
  for(const p of g.players){
    if(g.nightActions[p.id]?.action!=='accuse')continue;
    g.accuseUsed[p.id]=true;
    const opponent=g.chars.find(c=>!c.npc && c.playerId!==p.id);
    if(opponent.team!=='kira'){
      g.winner='kira';g.endReason='false_accusation';g.phase='finished';
      g.events.push('捜査員の告発は誤りでした。キラ陣営の勝利！');
      return;
    }
    const partner=g.chars.find(c=>c.team==='kira'&&c.id!==opponent.id);
    pushPrivate(g,p.id,`告発成功：相手プレイヤーはキラ陣営。もう1人のキラ陣営は「${partner.name}（${LABEL[partner.role]}）」です。`,'accuse');
  }
  const humanL=g.players.find(p=>myself(g,p.id).role==='l');
  const humanDevotee=g.players.find(p=>myself(g,p.id).role==='devotee');
  const swap=humanDevotee && g.nightActions[humanDevotee.id]?.action==='swap';
  if(swap){g.swapUsed=true;pushPrivate(g,humanDevotee.id,'「ノートのすり替え」を使いました（命中・空振りは分かりません）。');}
  for(const p of g.players){
    const a=g.nightActions[p.id];
    if(a.action==='investigate') {
      g.investigationsUsed[p.id]=(g.investigationsUsed[p.id]||0)+1;
      const c=byId(g,a.target);
      let isKira=c.role==='kira';
      if(swap&&humanL?.id===p.id)isKira=!isKira;
      pushPrivate(g,p.id,`調査：${c.name}は「${isKira?'キラである':'キラではない'}」。`,'investigate');
    } else if(a.action==='search') {
      g.searchUsed[p.id]=true;const c=byId(g,a.target);
      pushPrivate(g,p.id,`捜査：${c.name}の役職は「${LABEL[c.role]}」。`,'search');
    }
  }
  if(g.round<4){
    const completedRound=g.round;
    g.round++;
    for(const m of g.allMissions.filter(m=>m.round===completedRound)){
      pushPrivate(g,m.selector,`第${completedRound}R / ${m.members.map(id=>byId(g,id).name).join('＋')} の任務は「${m.outcome?'成功':'失敗'}」。`,'mission');
    }
    if(g.round===4){
      g.threshold=g.allMissions.filter(m=>m.outcome).length>=2;
      g.events.push(`公式発表：4任務での成功は「${g.threshold?'2回以上':'2回未満'}」でした。`);
    }
    g.nightActions={};g.missions=[];g.votes={};
    if(completedRound===2||completedRound===3){g.phase='briefing';g.briefingReady={};}
    else setDiscussion(g,false,now);
  } else {
    setDiscussion(g,true,now);
  }
}

function view(g,pid,now=Date.now()){
  const self=myself(g,pid);if(!self)err('参加していません');
  const known={ [self.id]:self.role };
  if(self.role==='devotee'){
    for(const c of g.chars)known[c.id]=c.role;
  }
  const initial=g.phase==='finished';
  const missions=g.allMissions.map(m=>({id:m.id,round:m.round,selector:m.selector,members:m.members,
    // Never expose other selector's actual result before full reveal.
    ...(initial||(m.selector===pid&&g.round>m.round)?{outcome:m.outcome}:{})
  }));
  const votes=g.phase==='voting'?g.missions.filter(m=>m.members.includes(self.id)).map(m=>({id:m.id,members:m.members})):[];
  return {
    room:g.code, players:g.players, selfId:self.id, selfRole:self.role, selfTeam:self.team,
    characters:g.chars.map(c=>({id:c.id,name:c.name,npc:c.npc,knownRole:initial?c.role:(known[c.id]||null)})),
    round:g.round,phase:g.phase,version:VERSION,minutes:g.minutes,discussionUntil:g.discussionUntil,nightUntil:g.phase==='night'?g.nightUntil:null,
    roleReady:Boolean(g.roleReady[pid]),roleReadyCount:g.players.filter(p=>g.roleReady[p.id]).length,endedBy:g.endedBy,
    briefingReady:Boolean(g.briefingReady[pid]),
    briefing:g.phase==='briefing'?{completedRound:g.round-1,
      missions:g.allMissions.filter(m=>m.round===g.round-1&&m.selector===pid).map(m=>({id:m.id,members:m.members,outcome:m.outcome})),
      ...(g.round===4?{threshold:g.threshold}:{})
    }:null,
    discussionSeconds:g.discussionSeconds,finalDiscussionSeconds:g.finalDiscussionSeconds,
    readyCount:g.players.filter(p=>g.discussionReady[p.id]).length,
    discussionReady:Boolean(g.discussionReady[pid]),otherReady:g.players.find(p=>p.id!==pid)?.id in g.discussionReady,
    selectionSubmitted:Object.hasOwn(g.selections,pid), selections:g.phase==='voting'||g.phase==='night'||g.phase==='finished'?g.players.map(p=>({playerId:p.id,members:g.selections[p.id]})).filter(x=>x.members):[],
    missionVoting:g.phase==='voting'?g.missions.map(m=>({id:m.id,selector:m.selector,members:m.members})):[],
    hasVoted:Object.hasOwn(g.votes,pid), requiredVotes:votes,
    nightSubmitted:Object.hasOwn(g.nightActions,pid), nightAction:(g.nightActions[pid]?.action||null),
    investigationsLeft:2-(g.investigationsUsed[pid]||0),searchUsed:!!g.searchUsed[pid],accuseUsed:!!g.accuseUsed[pid],swapUsed:g.swapUsed,
    threshold:g.threshold,
    events:g.events.slice(-10), privateLogs:g.privateLogs[pid], missions,
    guessSubmitted:Object.hasOwn(g.guesses,pid), winner:g.winner,endReason:g.endReason,
    finalGuesses:initial?g.players.filter(p=>Object.hasOwn(g.guesses,p.id)).map(p=>({player:p.name,target:byId(g,g.guesses[p.id]).name})):[],
    guessesCount:Object.keys(g.guesses).length
  };
}

// God-view read-only spectator state. This is never delivered to a player token.
function spectatorView(g,now=Date.now()){
  const done=g.phase==='finished';
  return {
    spectator:true, room:g.code, version:VERSION, round:g.round,phase:g.phase,
    players:g.players,characters:g.chars.map(c=>({id:c.id,name:c.name,npc:c.npc,knownRole:c.role})),
    discussionUntil:g.discussionUntil,nightUntil:g.phase==='night'?g.nightUntil:null,
    discussionReadyCount:g.players.filter(p=>g.discussionReady[p.id]).length,
    roleReadyCount:g.players.filter(p=>g.roleReady[p.id]).length,
    briefingReadyCount:g.players.filter(p=>g.briefingReady[p.id]).length,
    selections:g.players.map(p=>({playerId:p.id,members:g.selections[p.id]||[]})),
    missions:g.allMissions.map(m=>({id:m.id,round:m.round,selector:m.selector,members:m.members,outcome:m.outcome})),
    missionVoting:g.missions.map(m=>({id:m.id,round:m.round,selector:m.selector,members:m.members,outcome:m.outcome})),
    nightActions:Object.fromEntries(g.players.map(p=>[p.id,g.nightActions[p.id]?.action||null])),
    threshold:g.threshold, events:g.events.slice(-20),
    privateLogs:Object.fromEntries(g.players.map(p=>[p.id,g.privateLogs[p.id]||[]])),
    guesses:done?Object.fromEntries(g.players.filter(p=>g.guesses[p.id]).map(p=>[p.id,g.guesses[p.id]])):{},
    winner:g.winner,endReason:g.endReason,endedBy:g.endedBy,
  };
}


import http from 'node:http';
import {randomBytes, randomInt} from 'node:crypto';

const ASSETS = {
  'index.html': Buffer.from('','base64'),
  'styles.css': Buffer.from('','base64'),
  'client.js': Buffer.from('','base64'),
  'roles/kira.webp': Buffer.from('','base64'),
  'roles/devotee.webp': Buffer.from('','base64'),
  'roles/l.webp': Buffer.from('','base64'),
  'roles/investigator.webp': Buffer.from('','base64')
};
const rooms=new Map();
const PORT=Number(process.env.PORT||3000);
const clients=new Set();
const MAX_ROOMS=500;
const code=()=>randomBytes(4).toString('hex').toUpperCase();
const token=()=>randomBytes(24).toString('hex');
const json=(res,status,obj,headers={})=>{res.writeHead(status,{'content-type':'application/json; charset=utf-8','cache-control':'no-store',...headers});res.end(JSON.stringify(obj));};
const failure=(res,e)=>json(res,e.status||400,{error:e.message||'操作に失敗しました'});
async function body(req){let data='';for await(const b of req){data+=b;if(data.length>16384)throw Error('データが大きすぎます');} try{return JSON.parse(data||'{}');}catch{throw Error('JSONが不正です');}}
function playerFor(room,secret){return room.players.find(p=>p.token===secret);}
function authorized(url,request,secretFallback){
  const code=url.searchParams.get('room')?.trim().toUpperCase();
  const room=rooms.get(code);
  if(!room)throw Error('ルームがありません');
  const secret=request.headers.authorization?.replace(/^Bearer\s+/i,'')||url.searchParams.get('token')||secretFallback;
  const player=playerFor(room,secret);
  const spectator=room.spectators?.has(secret) || false;
  if(!player && !spectator)throw Error('参加認証に失敗しました');
  return {room,player,spectator};
}
function publicRoom(room,pid,isSpectator=false){
  const common={code:room.code,matchId:room.matchId,spectatorCount:room.spectators.size,...(!isSpectator&&pid==='p1'?{spectatorInviteKey:room.spectatorKey}:{})};
  if(!room.game)return {...common,lobby:true,spectator:isSpectator,version:VERSION,players:room.players.map(p=>({id:p.id,name:p.name})),selfId:isSpectator?null:pid,settings:room.settings};
  const data=isSpectator?spectatorView(room.game):view(room.game,pid);
  return {...common,lobby:false,...data,rematchReadyCount:room.rematchReady.size,rematchReady:!isSpectator&&room.rematchReady.has(pid)};
}
function broadcast(room){
  for(const sub of [...room.subs]) {
    try{sub.res.write(`data: ${JSON.stringify(publicRoom(room,sub.id,sub.spectator))}\n\n`);}catch{room.subs.delete(sub);}
  }
}
function roomAction(room,fn){
  if(room.game)tick(room.game);
  const answer=fn();
  broadcast(room);return answer;
}
const routes={'/':'index.html','/index.html':'index.html','/styles.css':'styles.css','/client.js':'client.js',
  '/roles/kira.webp':'roles/kira.webp','/roles/devotee.webp':'roles/devotee.webp','/roles/l.webp':'roles/l.webp','/roles/investigator.webp':'roles/investigator.webp'};
const types={'.html':'text/html; charset=utf-8','.js':'text/javascript; charset=utf-8','.css':'text/css; charset=utf-8','.webp':'image/webp'};
const server=http.createServer(async(req,res)=>{
  const url=new URL(req.url,`http://${req.headers.host||'localhost'}`);
  try{
    if(req.method==='GET'&&url.pathname==='/health'){json(res,200,{ok:true,rooms:rooms.size});return;}
    if(req.method==='GET'&&routes[url.pathname]){
      const file=routes[url.pathname];
      const data=ASSETS[file];
      res.writeHead(200,{'content-type':types[file.slice(file.lastIndexOf('.'))],'cache-control':'no-cache','x-content-type-options':'nosniff','content-security-policy':"default-src 'self'; connect-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self'; img-src 'self' data:; base-uri 'self'; form-action 'self'"});
      res.end(data);return;
    }
    if(req.method==='POST'&&url.pathname==='/api/create'){
      if(rooms.size>=MAX_ROOMS)throw Error('ルーム数の上限に達しました');
      const data=await body(req);
      const name=String(data.name||'').trim().slice(0,20);
      if(!name)throw Error('名前を入力してください');
      let id;do{id=code();}while(rooms.has(id));
      const p={id:'p1',name,token:token()};
      const room={code:id,players:[p],spectators:new Map(),spectatorKey:token(),matchId:0,rematchReady:new Set(),game:null,settings:{discussionSeconds:120,finalDiscussionSeconds:120},subs:new Set(),lastActive:Date.now()};
      rooms.set(id,room);json(res,200,{room:id,token:p.token,playerId:p.id});return;
    }
    if(req.method==='POST'&&url.pathname==='/api/spectate'){
      const data=await body(req);
      const id=String(data.room||'').trim().toUpperCase();
      const room=rooms.get(id);if(!room||String(data.key||'')!==room.spectatorKey)throw Error('観戦用招待URLが必要です');
      if(room.spectators.size>=50)throw Error('観戦者数が上限に達しました');
      const watchToken=token();room.spectators.set(watchToken,Date.now());
      room.lastActive=Date.now();
      json(res,200,{room:id,token:watchToken,spectator:true});broadcast(room);return;
    }
    if(req.method==='POST'&&url.pathname==='/api/join'){
      const data=await body(req);
      const id=String(data.room||'').trim().toUpperCase();
      const room=rooms.get(id);if(!room)throw Error('ルームが見つかりません');
      if(room.game||room.players.length>=2)throw Error('このルームはすでに満員です');
      const name=String(data.name||'').trim().slice(0,20);
      if(!name)throw Error('名前を入力してください');
      const p={id:'p2',name,token:token()};room.players.push(p);room.lastActive=Date.now();
      json(res,200,{room:id,token:p.token,playerId:p.id});broadcast(room);return;
    }
    if(req.method==='GET'&&url.pathname==='/api/state'){
      const {room,player,spectator}=authorized(url,req);
      if(room.game)roomAction(room,()=>null);
      json(res,200,publicRoom(room,player?.id,spectator));return;
    }
    if(req.method==='GET'&&url.pathname==='/api/events'){
      const {room,player,spectator}=authorized(url,req);
      res.writeHead(200,{'content-type':'text/event-stream; charset=utf-8','cache-control':'no-cache, no-transform','connection':'keep-alive','x-accel-buffering':'no'});
      const sub={res,id:player?.id||null,spectator};room.subs.add(sub);
      res.write(`data: ${JSON.stringify(publicRoom(room,player?.id,spectator))}\n\n`);
      const pulse=setInterval(()=>{try{if(room.game) {const moved=tick(room.game);if(moved)broadcast(room);}res.write(': ping\n\n');}catch{clearInterval(pulse);room.subs.delete(sub);}},1000);
      req.on('close',()=>{clearInterval(pulse);room.subs.delete(sub);});return;
    }
    if(req.method==='POST'&&url.pathname==='/api/config'){
      const data=await body(req);const fakeUrl=new URL(`http://localhost/?room=${encodeURIComponent(data.room||'')}`);
      const {room,player}=authorized(fakeUrl,req,data.token);
      if(!player||room.players[0].id!==player.id||room.game)throw Error('ルーム作成者が開始前に設定できます');
      const valid=[30,60,90,120,180,240,300,420,600,900,1200];
      const discussionSeconds=Number(data.discussionSeconds);
      const finalDiscussionSeconds=Number(data.finalDiscussionSeconds);
      if(!valid.includes(discussionSeconds)||!valid.includes(finalDiscussionSeconds))throw Error('議論時間は候補から選んでください');
      room.settings={discussionSeconds,finalDiscussionSeconds};
      roomAction(room,()=>null);
      json(res,200,{ok:true,settings:room.settings});return;
    }
    if(req.method==='POST'&&url.pathname==='/api/start'){
      const data=await body(req);const fakeUrl=new URL(`http://localhost/?room=${encodeURIComponent(data.room||'')}`);
      const {room,player}=authorized(fakeUrl,req,data.token);
      if(!player||room.players[0].id!==player.id)throw Error('ルーム作成者だけが開始できます');
      if(room.players.length!==2||room.game)throw Error('2人揃った未開始のルームだけ開始できます');
      roomAction(room,()=>{room.game=beginGame(room.players,room.settings);room.game.code=room.code;room.matchId++;room.rematchReady.clear();});
      json(res,200,{ok:true});return;
    }
    if(req.method==='POST'&&url.pathname==='/api/rematch'){
      const data=await body(req);const fakeUrl=new URL(`http://localhost/?room=${encodeURIComponent(data.room||'')}`);
      const {room,player}=authorized(fakeUrl,req,data.token);
      if(!player)throw Error('観戦者は再戦操作ができません');
      if(!room.game||!['finished','abandoned'].includes(room.game.phase))throw Error('終了した試合でのみ再戦できます');
      roomAction(room,()=>{room.rematchReady.add(player.id);if(room.rematchReady.size===2){room.game=beginGame(room.players,room.settings);room.game.code=room.code;room.matchId++;room.rematchReady.clear();}});
      json(res,200,{ok:true});return;
    }
    if(req.method==='POST'&&url.pathname==='/api/action'){
      const data=await body(req);const fakeUrl=new URL(`http://localhost/?room=${encodeURIComponent(data.room||'')}`);
      const {room,player}=authorized(fakeUrl,req,data.token);
      if(!player)throw Error('観戦者はゲームを操作できません');
      if(!room.game)throw Error('ゲームはまだ開始していません');
      roomAction(room,()=>act(room.game,player.id,data));
      json(res,200,{ok:true});return;
    }
    json(res,404,{error:'ページが見つかりません'});
  }catch(e){failure(res,e);}
});
// Empty rooms and completed matches are temporary; free hosting may restart at any time.
const sweep=setInterval(()=>{
  const now=Date.now();for(const [id,room] of rooms){if(room.game&&tick(room.game,now))broadcast(room);
    if(now-room.lastActive>24*3600_000&&room.subs.size===0)rooms.delete(id);
  }
},1000);sweep.unref();
server.listen(PORT,'0.0.0.0',()=>console.log(`SUPER KIRA GAME → http://localhost:${PORT}`));
export {server,rooms};
